#!/bin/sh
# mkengine.sh: builds decor/scene/engine.js, the flower engine the shop's pre-drawing needs (buildBq, growBq, aliveBq, the vessels
# and the model bouquets), from the validated modules of demo/src. Since 2026-10-15 the page no longer loads it:
# predessin.mjs runs it once per product and writes decor/scene/bouquets/<id>/. The modules are never edited here: they are concatenated in the
# order of flower-atelier/mkapp.sh, without the old shop's page (a1.html) and interface (u1.js, u2.js, w1.js, u3.js).
#
#   sh decor/scene/mkengine.sh [src dir]
#
# A short prelude gives the engine the one element of the old page it reads while loading: the shared <defs id="defs"> (p2.js).
# A listed module that is missing stops the build.
set -e
HERE="$(cd "$(dirname "$0")" && pwd)"
SRC="${1:-$HERE/../../demo/src}"
OUT="$HERE/engine.js"
cd "$SRC"
MODS="p2.js p3.js p4.js b1.js b2.js b5.js d1.js d2.js d3.js d4.js d5.js e1.js e2.js v0.js v1a.js v1b.js v1c.js v1d.js v1e.js v1f.js v1h.js v1g.js v1i.js c2.js e3.js f1.js e4.js e5.js e6.js s0.js l0.js s1a.js s1b.js s1c.js s1d.js s1e.js s2a.js s3a.js s4a.js s5a.js s6a.js s7a.js s8a.js s9a.js s10a.js s11a.js s12a.js s13a.js r1a.js r2a.js r3a.js r4a.js r6a.js s20a.js s14a.js s19a.js s21a.js s22a.js s17a.js s24a.js s27a.js s25a.js s26a.js r5a.js s16a.js s18a.js s28a.js s15a.js s30a.js s32a.js s29a.js s34a.js s23a.js s31a.js s35a.js s36a.js s37a.js s39a.js s41a.js s33a.js s38a.js s40a.js s42a.js s44a.js s46a.js s45a.js s49a.js s53a.js s48a.js s50a.js s54a.js s55a.js s43a.js s47a.js s51a.js s56a.js s57a.js s58a.js s59a.js s60a.js s62a.js s52a.js s61a.js s64a.js s65a.js s66a.js s67a.js s63a.js s68a.js s69a.js s74a.js s75a.js s79a.js s70a.js s71a.js s72a.js s73a.js s77a.js s78a.js s80a.js s81a.js s83a.js s76a.js s82a.js s84a.js s85a.js s86a.js s87a.js s88a.js s90a.js s91a.js s92a.js s93a.js s95a.js s96a.js s99a.js s101a.js s102a.js s89a.js s94a.js s97a.js s98a.js s100a.js s103a.js s104a.js s105a.js s106a.js s107a.js s108a.js z2.js z1.js z3.js z6.js c4.js c5.js z5.js y1.js y3.js $(ls y3-*.js 2>/dev/null) y2.js $(ls y-*.js 2>/dev/null) $(ls yz-*.js 2>/dev/null) $(ls z7-*.js 2>/dev/null) k0.js k1.js k2.js"
miss=""
for m in $MODS; do [ -f "$m" ] || miss="$miss $m"; done
if [ -n "$miss" ]; then echo "modules absents :$miss" >&2; exit 1; fi
{
  printf '/* engine.js: generated by decor/scene/mkengine.sh from %s (%s), never edit by hand */\n' "$SRC" "$(date -u +%Y-%m-%dT%H:%MZ)"
  printf '%s\n' "/* prelude: the shared gradients and shadows of the drawings live in one hidden <defs id=\"defs\"> (read by p2.js) */" \
    "{if(!document.getElementById('defs')){const s=document.createElementNS('http://www.w3.org/2000/svg','svg');s.setAttribute('width','0');s.setAttribute('height','0');s.setAttribute('aria-hidden','true');s.setAttribute('focusable','false');s.style.cssText='position:absolute;width:0;height:0;overflow:hidden';s.innerHTML='<defs id=\"defs\"></defs>';(document.body||document.documentElement).prepend(s)}}"
  for m in $MODS; do cat "$m"; printf '\n'; done
  printf '%s\n' "/* end of the engine */" "window.ENGINE_OK=true;"
} > "$OUT"
node -e "const s=require('fs').readFileSync(process.argv[1],'utf8');try{new Function(s);console.log('engine.js : syntaxe ok,',Math.round(s.length/1024)+' Ko,',process.argv[2],'modules')}catch(e){console.log('engine.js : ERREUR',e.message);process.exit(1)}" "$OUT" "$(echo $MODS | wc -w)"
gzip -9 -c "$OUT" | wc -c | awk '{printf "engine.js : %d Ko en gzip -9\n", $1/1024}'
